// Changes: Project store tests over an in-memory SQLite database with a fake clock.

import { beforeEach, describe, expect, it } from 'vitest'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { openDatabase } from './db.server'
import { createProjectStore, type ProjectStore } from './projects.server'

const MINUTE = 60_000

let time: number
let store: ProjectStore

const advance = (ms: number) => {
  time += ms
}

const withGrammar = (grammar: string): ProjectData => {
  const data = defaultProjectData()
  return { ...data, ll: { ...data.ll, grammar } }
}

beforeEach(() => {
  time = Date.parse('2026-01-01T10:00:00.000Z')
  store = createProjectStore(openDatabase(':memory:'), { now: () => new Date(time) })
})

describe('saving', () => {
  it('bumps the revision on each change and reports a conflict for a stale base revision', () => {
    const project = store.createProject('P', defaultProjectData())
    expect(project.revision).toBe(1)

    advance(1000)
    expect(store.saveProject(project.id, withGrammar('S -> a'), 1)).toEqual({
      status: 'saved',
      revision: 2,
      updatedAt: '2026-01-01T10:00:01.000Z',
    })

    const stale = store.saveProject(project.id, withGrammar('S -> b'), 1)
    expect(stale.status).toBe('conflict')
    expect(stale.status === 'conflict' && stale.project.data.ll.grammar).toBe('S -> a')
    expect(store.getProject(project.id)?.revision).toBe(2)
  })
})

describe('automatic snapshots', () => {
  it('backs up the previous state at most every 20 minutes', () => {
    const { id } = store.createProject('P', withGrammar('v1'))
    store.saveProject(id, withGrammar('v2'), 1)
    advance(19 * MINUTE)
    store.saveProject(id, withGrammar('v3'), 2)
    advance(1 * MINUTE)
    store.saveProject(id, withGrammar('v4'), 3)

    const autos = store.listSnapshots(id).filter((s) => s.kind === 'auto')
    expect(autos.map((s) => s.createdAt)).toEqual(['2026-01-01T10:20:00.000Z', '2026-01-01T10:00:00.000Z'])
  })

  it('keeps only the last 30 automatic snapshots and never prunes named versions', () => {
    const { id } = store.createProject('P', withGrammar('v0'))
    store.createSnapshot(id, 'Moja verzia')
    for (let i = 1; i <= 35; i++) {
      advance(20 * MINUTE)
      store.saveProject(id, withGrammar(`v${i}`), i)
    }
    const snapshots = store.listSnapshots(id)
    expect(snapshots.filter((s) => s.kind === 'auto')).toHaveLength(30)
    expect(snapshots.filter((s) => s.kind === 'named').map((s) => s.label)).toEqual(['Moja verzia'])
  })
})

describe('restore and safety snapshots', () => {
  it('restores a version and keeps the replaced state as a safety snapshot, distinct from named versions', () => {
    const { id } = store.createProject('P', withGrammar('old'))
    const named = store.createSnapshot(id, 'Pred zmenou')!
    expect(named).toMatchObject({ label: 'Pred zmenou', kind: 'named', auto: false })
    store.saveProject(id, withGrammar('new'), 1)

    const restored = store.restoreSnapshot(id, named.id)!
    expect(restored.data.ll.grammar).toBe('old')
    expect(restored.revision).toBe(3)

    const safety = store.listSnapshots(id).filter((s) => s.kind === 'safety')
    expect(safety.map((s) => s.label)).toEqual(['Pred obnovením „Pred zmenou“'])
    const restoredBack = store.restoreSnapshot(id, safety[0].id)!
    expect(restoredBack.data.ll.grammar).toBe('new')
  })

  it('keeps only the last 10 safety snapshots', () => {
    const { id } = store.createProject('P', withGrammar('v0'))
    for (let i = 1; i <= 12; i++) store.replaceProjectData(id, withGrammar(`v${i}`), `Pred importom ${i}.json`)
    const safety = store.listSnapshots(id).filter((s) => s.kind === 'safety')
    expect(safety).toHaveLength(10)
    expect(safety[0].label).toBe('Pred importom 12.json')
  })

  it('refuses to restore or delete a snapshot through another project', () => {
    const a = store.createProject('A', withGrammar('a'))
    const b = store.createProject('B', withGrammar('b'))
    const snapA = store.createSnapshot(a.id, 'A1')!

    expect(store.restoreSnapshot(b.id, snapA.id)).toBeNull()
    expect(store.getProject(b.id)?.data.ll.grammar).toBe('b')
    expect(store.listSnapshots(b.id)).toEqual([])

    expect(store.deleteSnapshot(b.id, snapA.id)).toBe(false)
    expect(store.listSnapshots(a.id).map((s) => s.id)).toEqual([snapA.id])
    expect(store.deleteSnapshot(a.id, snapA.id)).toBe(true)
    expect(store.listSnapshots(a.id)).toEqual([])
  })
})

describe('write invariants', () => {
  it('decodes documents on write (old versions, unknown fields, invalid cells)', () => {
    const legacy = {
      app: 'ifj26-table-maker',
      version: 1,
      ll: { grammar: 'S -> a', input: '', sim: { step: 3, speed: 2 } },
      prec: { terminals: ['$', '+'], cells: { a: '?' }, gen: { levels: '+' } },
      extra: 'x',
    }
    const { id } = store.createProject('P', legacy)
    const stored = store.getProject(id)!
    expect(stored.data.version).toBe(2)
    expect(stored.data.ll).toEqual({ grammar: 'S -> a', input: '' })
    expect(stored.data.prec).toEqual({ terminals: ['+'], cells: {}, rules: '', input: '' })
    expect(stored.data).not.toHaveProperty('extra')
  })

  it('rejects documents over the size limit', () => {
    const { id } = store.createProject('P', defaultProjectData())
    const huge = withGrammar('x'.repeat(2_000_001))
    expect(() => store.saveProject(id, huge, 1)).toThrow('Projekt je príliš veľký')
    expect(() => store.createProject('Q', huge)).toThrow('Projekt je príliš veľký')
    expect(store.getProject(id)?.revision).toBe(1)
  })

  it('trims and cuts project names to 120 characters, rejecting empty ones', () => {
    const project = store.createProject(`  ${'n'.repeat(150)}  `, defaultProjectData())
    expect(project.name).toBe('n'.repeat(120))
    expect(() => store.renameProject(project.id, '   ')).toThrow()
    expect(store.renameProject(project.id, ' Nový ')?.name).toBe('Nový')
  })

  it('deletes the snapshots together with the project', () => {
    const { id } = store.createProject('P', withGrammar('a'))
    store.createSnapshot(id, 'S')
    store.deleteProject(id)
    expect(store.getProject(id)).toBeNull()
    expect(store.listSnapshots(id)).toEqual([])
    expect(store.listProjects()).toEqual([])
  })
})

describe('view state', () => {
  it('saves the simulation state without touching the revision or the history', () => {
    const project = store.createProject('P', withGrammar('a'))
    expect(project.view).toEqual({ llSim: { step: 0, speed: 1 } })

    expect(store.saveViewState(project.id, { llSim: { step: 7, speed: 3 } })).toEqual({ llSim: { step: 7, speed: 3 } })
    const after = store.getProject(project.id)!
    expect(after.view).toEqual({ llSim: { step: 7, speed: 3 } })
    expect(after.revision).toBe(1)
    expect(after.updatedAt).toBe(project.updatedAt)
    expect(store.listSnapshots(project.id)).toEqual([])
  })

  it('reports a missing project', () => {
    expect(store.saveViewState('nope', { llSim: { step: 1, speed: 1 } })).toBeNull()
  })
})
